(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20 + Math.cos(y*0.013-t*0.18)*14;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12;
  const w2x = Math.sin((x+w1x)*0.009+t*0.15)*10 + Math.cos((y+w1y)*0.011-t*0.12)*8;
  const w2y = Math.cos((y+w1y)*0.01+t*0.17)*9 + Math.sin((x+w1x)*0.008-t*0.14)*7;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.075, 2.1, 0.9],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.095, 1.8, 1.1],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.4, 0.8],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.6, 1.2],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.7, 0.7],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.085, 2.0, 1.0],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.1, 1.4, 1.3],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*40, 0.07, 2.2, 0.85]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a = Math.sin(d*f-t*sp);
    const b = Math.sin(d*f*0.7+t*sp*0.6+1.5);
    const c = Math.sin(d*f*1.3-t*sp*0.8+3.0)*0.5;
    aS += a*w; iS += b*w; cS += c*w;
  }
  const tw = 7.6;
  const act=aS/tw, inh=iS/tw, cross=cS/tw;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0))/2
    + Math.sin((sx+sy)*0.11+t*2.2)*0.2 + Math.sin((sx-sy)*0.09-t*1.8)*0.2
    + Math.sin(sx*0.06+t*1.5)*Math.sin(sy*0.05-t*1.2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3-t*1.4)+Math.sin(dist*0.038+ang*4-t*1.1))*0.35
    + Math.sin(dist*0.06-ang*2+t*0.8)*0.15;
  const turb = Math.sin(sx*0.08+sy*0.06+t*1.3)*Math.cos(sx*0.05-sy*0.09-t*0.9)*0.2;
  const lap = Math.sin(sx*0.2)*Math.sin(sy*0.2)+Math.sin((sx+sy)*0.15+t*0.5)*Math.sin((sx-sy)*0.12-t*0.7);
  const reaction = Math.tanh((act - inh*0.65 + cross*0.4 + bg*0.25 + spiral + turb + lap*0.15)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.5+Math.sin(sx*0.07-t*0.8)*Math.cos(sy*0.11+t*0.6)*0.3)*1.4)*0.25;
  const fiber = Math.sin(sy*0.25+Math.sin(sx*0.03+t*0.5)*3+t*0.4)*0.08;
  const blend = reaction*0.65+cell*0.2+fiber, v = blend*0.5+0.5;
  const pal = [
    [5,12,55],[12,45,95],[18,85,125],[25,130,135],
    [60,165,130],[140,190,90],[210,190,60],[225,150,55],
    [210,100,65],[175,60,70],[120,35,75],[65,20,60],[30,12,52],[5,12,55]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12:1.0;
  const glow=Math.max(0,1-Math.abs(reaction)*1.5)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
